import {upgradeAnimals,setAnimalMotion,animateRigDetails} from './animal-assets.js?v=track8';
import {animalIdentity} from './animal-identity.js?v=breeding9';
import * as T from './three.module.js';import {FARMS,ensureFarms} from './regional-farms.js?v=landscape13';import {treeGrove,detailHouse,contactShadow} from './landscape-assets.js?v=landscape13';
export function buildRegionalWorld({scene,register,block,mats,mobile=false,save=()=>{},loadAnimals=true}){
 const boxGeo=new T.BoxGeometry(1,1,1),materials=new Map(),farms=new Map(),roadParts=[];let collecting=true;
 function cube(parent,w,h,d,c,x,y,z){if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,map:mats.wood?.map||null,roughness:.9}));const m=new T.Mesh(boxGeo,materials.get(c));m.scale.set(w,h,d);m.position.set(x,y,z);m.receiveShadow=true;parent.add(m);if(parent===scene&&collecting)roadParts.push(m);return m;}
 function road(x,z,w,d){cube(scene,w,.05,d,'#777c70',x,.25,z);const long=w>d,limit=long?w:d;for(let i=-limit/2+3;i<limit/2;i+=8)cube(scene,long?2:.12,.025,long?.12:2,'#e6d9b2',x+(long?i:0),.29,z+(long?0:i));cube(scene,w+(long?0:2),.025,d+(long?2:0),'#b6b492',x,.2,z);}
 road(-132,30,7,300);road(144,30,7,300);road(6,-100,276,7);road(6,164,276,7);road(-90,44,84,7);road(104,44,80,7);for(const p of FARMS)road((p.x+(p.x<0?-132:144))/2,p.approach.z,Math.abs(p.x-(p.x<0?-132:144))+8,5);
 collecting=false;for(const mat of new Set(roadParts.map(m=>m.material))){const list=roadParts.filter(m=>m.material===mat),batch=new T.InstancedMesh(boxGeo,mat,list.length);batch.name='Regional road batch';batch.receiveShadow=true;list.forEach((m,i)=>{m.updateMatrix();batch.setMatrixAt(i,m.matrix);m.removeFromParent();});batch.computeBoundingSphere();scene.add(batch);}
 // Terrain continues beyond the playable region, hiding the former floating board edge.
 const terrainGeo=new T.PlaneGeometry(2000,1800,48,44);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),out=Math.max(0,Math.abs(x-6)-272,Math.abs(z)-244);pos.setY(i,-.12+Math.min(75,out*.13)*(1+.25*Math.sin(x*.016)*Math.cos(z*.019)));}terrainGeo.computeVertexNormals();const terrain=new T.Mesh(terrainGeo,new T.MeshStandardMaterial({color:'#849d6c',map:mats.grass.map,roughness:1}));terrain.name='Continuous rolling horizon';terrain.receiveShadow=true;scene.add(terrain);
 function label(g,text,x,y,z){const c=document.createElement('canvas');c.width=512;c.height=96;const ctx=c.getContext('2d');ctx.fillStyle='#f7efdb';ctx.fillRect?.(0,0,512,96);ctx.fillStyle='#344f3c';ctx.font='bold 25px system-ui';ctx.textAlign='center';ctx.fillText(text,256,59);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c)}));s.position.set(x,y,z);s.scale.set(12,2.25,1);g.add(s);}
 function homestead(g,p,x,z,w,d,h,color){const shell=new T.Group();g.add(shell);contactShadow(shell,x,z,w,d);cube(shell,w,h,d,color,x,h/2+.2,z);const pitch=.36,half=w/2+.6;for(const side of [-1,1]){const r=cube(shell,half/Math.cos(pitch),.2,d+1.3,p.roof,x+side*half/2,h+.25+half*Math.tan(pitch)/2,z);r.rotation.z=-side*pitch;}cube(shell,2,3,.15,'#665d4b',x,1.7,z+d/2+.1);for(const xx of [-w*.28,w*.28])cube(shell,2,1.7,.15,'#99b8b6',x+xx,3.2,z+d/2+.12);detailHouse({parent:shell,x,z,w,d,h,cube,roof:p.roof});register(shell,{kind:'regionalFarm',farmId:p.id,x:p.x,z:p.z,approach:p.approach});}
 for(const p of FARMS){const root=new T.Group();root.name=p.name;scene.add(root);const shell=cube(root,16,6,12,p.color,p.x,3.2,p.z-10);const proxy=new T.Group();proxy.position.set(p.approach.x,0,p.approach.z-5);scene.add(proxy);cube(proxy,3,1.8,.2,'#efe1b9',0,2,0);register(proxy,{kind:'regionalFarm',farmId:p.id,x:p.x,z:p.z,approach:p.approach});block(p.x,p.z-10,16,12);block(p.x+17,p.z-8,10,9);
  farms.set(p.id,{root,shell,loaded:false,growth:null});
 }
 function build(p,v){const g=v.root;v.shell.visible=false;homestead(g,p,p.x,p.z-10,16,12,6,p.color);homestead(g,p,p.x+17,p.z-8,10,9,4.5,p.kind==='dairy'?'#b7c2af':p.color);cube(g,8,.05,44,'#c0af89',p.x,.25,p.z+10);label(g,p.name.toUpperCase(),p.x,11,p.z);
  const grow=new T.Group();g.add(grow);v.growth=grow;
  if(p.kind==='crop'){for(let i=0;i<9;i++){cube(g,21,.08,.4,'#72543a',p.x-16,.3,p.z-14+i*4);cube(grow,20,.9,1.2,'#9aae58',p.x-16,.72,p.z-14+i*4);}}
  else if(p.kind==='orchard'){treeGrove(g,p.x-16,p.z+7,12,9);for(let i=0;i<8;i++)cube(grow,.3,.3,.3,'#d79a53',p.x-22+(i%4)*4,3,p.z+3+Math.floor(i/4)*8);}
  else {cube(g,21,.05,23,'#a8b984',p.x-17,.24,p.z+3);for(const z of [-9,15]){for(let i=0;i<8;i++)cube(g,.15,1.3,.15,'#b9ac8a',p.x-28+i*3,.9,p.z+z);cube(g,21,.12,.12,'#e8e2c9',p.x-17,1.2,p.z+z);}for(let i=0;i<5;i++)cube(grow,1.1,.8,.8,'#d7bf79',p.x-23+i*2.5,.7,p.z+12);}
  for(const x of [-p.w/2,p.w/2])for(let i=0;i<6;i++)cube(g,.16,1.4,.16,'#ad9b76',p.x+x,.95,p.z-p.d/2+i*8);treeGrove(g,p.x+17,p.z+18,7,7);v.animals=[];if(loadAnimals&&['dairy','boarding'].includes(p.kind)){for(let i=0;i<2;i++){const root=new T.Group();root.position.set(p.x-21+i*7,.2,p.z+2);g.add(root);contactShadow(g,p.x-21+i*7,p.z+2,2,3.5);const type=p.kind==='dairy'?'cow':'horse',key='regional-'+p.id+'-'+i;v.animals.push({g:root,type,legs:[],appearanceSlot:animalIdentity(lastState,type,key,i).coatId});root.userData={type,name:p.name+' resident '+(i+1),appearanceKey:key};}v.modelStatus='loading';upgradeAnimals(v.animals,()=>{for(const a of v.animals)if(a.model&&!a.registered){register(a.model,{kind:'regionalFarm',farmId:p.id,x:p.x,z:p.z,approach:p.approach});a.registered=true;}}).then(()=>{v.modelStatus=v.animals.every(a=>a.nativeRig)?'animated models loaded':'Some resident models unavailable';save();});}v.loaded=true;
 }
 const groves=[[-112,-70],[112,-72],[-112,85],[112,85],[-210,-15],[220,10],[0,-180],[0,190]].map(([x,z])=>{const root=new T.Group();root.name='Regional woodland';scene.add(root);return {root,x,z,loaded:false};});
 let lastState,elapsed=0;return {farms,terrain,update(dt,player,state,focus=player){lastState=state;elapsed+=dt;for(const grove of groves){const near=Math.min(Math.hypot(player.x-grove.x,player.z-grove.z),Math.hypot(focus.x-grove.x,focus.z-grove.z))<(mobile?100:160);if(near&&!grove.loaded){treeGrove(grove.root,grove.x,grove.z,14,13);grove.loaded=true;}grove.root.visible=near;}const own=ensureFarms(state).owned;for(const p of FARMS){const v=farms.get(p.id),d=Math.min(Math.hypot(player.x-p.x,player.z-p.z),Math.hypot(focus.x-p.x,focus.z-p.z));if(d<(mobile?80:125)&&!v.loaded)build(p,v);v.root.visible=d<(mobile?135:220);if(v.growth)v.growth.visible=!!own[p.id]?.job;for(const a of v.animals||[]){if(d<(mobile?85:135)&&a.mixer){setAnimalMotion(a,Math.floor(elapsed/8)%2?'eat':'idle',0);a.mixer.update(dt);animateRigDetails(a,dt);}}}},};
}
